"use client"

import { useState, useEffect } from "react"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import { getUserSettings, saveUserSettings, type UserSettings } from "@/lib/user-data"
import { useAuth } from "@/components/auth-provider"
import { LogOut, AlertCircle } from "lucide-react"

const avatars = [
  { id: "santa", emoji: "🎅", name: "Santa" },
  { id: "elf", emoji: "🧝", name: "Elf" },
  { id: "reindeer", emoji: "🦌", name: "Reindeer" },
  { id: "snowman", emoji: "☃️", name: "Snowman" },
] as const

export function ProfileTab({
  onSettingsChange,
}: {
  onSettingsChange: () => void
}) {
  const [settings, setSettings] = useState<UserSettings>(getUserSettings())
  const [mounted, setMounted] = useState(false)
  const { user, isGuest, signOut } = useAuth()

  useEffect(() => {
    setMounted(true)
    setSettings(getUserSettings())
  }, [])

  const updateSettings = (newSettings: UserSettings) => {
    setSettings(newSettings)
    saveUserSettings(newSettings)
  }

  if (!mounted) return null

  return (
    <div className="max-w-4xl mx-auto space-y-8">
      {isGuest && (
        <Card className="bg-yellow-600/20 border-yellow-600/50">
          <CardContent className="pt-6">
            <div className="flex items-start gap-3">
              <AlertCircle className="h-5 w-5 text-yellow-300 flex-shrink-0 mt-0.5" />
              <div>
                <h3 className="font-semibold text-yellow-300 mb-1">Guest Mode Active</h3>
                <p className="text-sm text-cream">
                  Your progress is not being saved. Create an account to save your data permanently.
                </p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      <Card
        className="border border-green-800/30"
        style={{
          backgroundImage: "url('/images/paper.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        <CardHeader>
          <CardTitle className="text-2xl text-yellow-300">Your Profile</CardTitle>
          <CardDescription className="text-cream">Customize your study buddy</CardDescription>
        </CardHeader>

        <CardContent className="space-y-6">
          {user && !isGuest && (
            <div className="p-4 rounded-lg bg-white/10 border border-green-800/30">
              <Label className="text-yellow-300">Email</Label>
              <p className="text-cream mt-1">{user.email}</p>
            </div>
          )}

          <div className="space-y-2">
            <Label className="text-yellow-300">Display Name</Label>
            <Input
              value={settings.name}
              onChange={(e) => updateSettings({ ...settings, name: e.target.value })}
              className="bg-white/10 border-green-800/30 text-cream placeholder:text-cream/50"
            />
          </div>

          <div className="space-y-3">
            <Label className="text-yellow-300">Choose Avatar</Label>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
              {avatars.map((avatar) => {
                const active = settings.avatar === avatar.id
                return (
                  <button
                    key={avatar.id}
                    onClick={() => updateSettings({ ...settings, avatar: avatar.id })}
                    className={`flex flex-col items-center gap-2 p-4 rounded-xl border transition-all ${
                      active
                        ? "border-accent bg-white/20 scale-105"
                        : "border-green-800/30 bg-white/10 hover:border-accent"
                    }`}
                  >
                    <div className="text-5xl">{avatar.emoji}</div>
                    <span className="text-sm text-cream">{avatar.name}</span>
                  </button>
                )
              })}
            </div>
          </div>
        </CardContent>
      </Card>

      <Card
        className="border border-green-800/30"
        style={{
          backgroundImage: "url('/images/paper.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        <CardHeader>
          <CardTitle className="text-2xl text-yellow-300">App Settings</CardTitle>
          <CardDescription className="text-cream">Control app behavior</CardDescription>
        </CardHeader>

        <CardContent className="space-y-6">
          {[
            {
              title: "Theme Mode",
              desc: "Festive or minimal",
              checked: settings.theme === "festive",
              onToggle: () => {
                updateSettings({
                  ...settings,
                  theme: settings.theme === "festive" ? "minimal" : "festive",
                })
                onSettingsChange()
              },
            },
            {
              title: "Snow Animation",
              desc: "Background snow",
              checked: settings.snowEnabled,
              onToggle: () => {
                updateSettings({
                  ...settings,
                  snowEnabled: !settings.snowEnabled,
                })
                onSettingsChange()
              },
            },
            {
              title: "Sound Effects",
              desc: "UI sounds",
              checked: settings.soundEnabled,
              onToggle: () =>
                updateSettings({
                  ...settings,
                  soundEnabled: !settings.soundEnabled,
                }),
            },
          ].map((item, i) => (
            <div
              key={i}
              className="flex items-center justify-between p-4 rounded-lg bg-white/10 border border-green-800/30"
            >
              <div>
                <Label className="text-yellow-300">{item.title}</Label>
                <p className="text-sm text-cream">{item.desc}</p>
              </div>
              <Switch
                checked={item.checked}
                onCheckedChange={item.onToggle}
                className="data-[state=checked]:bg-accent"
              />
            </div>
          ))}
        </CardContent>
      </Card>

      <Card
        className="border border-green-800/30"
        style={{
          backgroundImage: "url('/images/paper.jpg')",
          backgroundSize: "cover",
          backgroundPosition: "center",
        }}
      >
        <CardHeader>
          <CardTitle className="text-yellow-300">Data Management</CardTitle>
          <CardDescription className="text-cream">Export or reset progress</CardDescription>
        </CardHeader>

        <CardContent className="space-y-4">
          <div className="flex flex-col sm:flex-row gap-3">
            <Button
              variant="outline"
              className="flex-1 bg-white/10 text-cream border-green-800 hover:bg-white/20"
              onClick={() => {
                if (confirm("Export your data?")) {
                  const data = {
                    settings: getUserSettings(),
                    stats: localStorage.getItem("userStats"),
                    tasks: localStorage.getItem("tasks"),
                    quests: localStorage.getItem("quests"),
                    gifts: localStorage.getItem("gifts"),
                  }
                  const blob = new Blob([JSON.stringify(data, null, 2)], { type: "application/json" })
                  const url = URL.createObjectURL(blob)
                  const a = document.createElement("a")
                  a.href = url
                  a.download = "holiday-study-buddy-data.json"
                  a.click()
                }
              }}
            >
              Export Data
            </Button>
            <Button
              variant="destructive"
              className="flex-1 bg-red-600 hover:bg-red-700"
              onClick={() => {
                if (confirm("Reset all data? This cannot be undone!")) {
                  localStorage.clear()
                  window.location.reload()
                }
              }}
            >
              Reset All Data
            </Button>
          </div>

          {!isGuest && (
            <Button
              variant="outline"
              className="w-full bg-white/10 text-yellow-300 border-accent hover:bg-white/20"
              onClick={signOut}
            >
              <LogOut className="mr-2 h-4 w-4" />
              Logout
            </Button>
          )}
        </CardContent>
      </Card>
    </div>
  )
}
