"use client"

export interface Task {
  id: string
  title: string
  completed: boolean
  createdAt: Date
}

export interface Quest {
  id: string
  title: string
  description: string
  progress: number
  target: number
  completed: boolean
  xpReward: number
  type: "daily" | "weekly"
}

export interface Gift {
  id: string
  title: string
  description: string
  unlocked: boolean
  xpCost: number
  reward: string
}

export interface UserStats {
  level: number
  xp: number
  totalFocusMinutes: number
  todayFocusMinutes: number
  weekFocusMinutes: number
  tasksCompleted: number
  currentStreak: number
  badges: string[]
}

export interface UserSettings {
  name: string
  avatar: "santa" | "elf" | "reindeer" | "snowman"
  theme: "festive" | "minimal"
  snowEnabled: boolean
  soundEnabled: boolean
}

import { getAuthState } from "./auth"

const API_URL = "http://127.0.0.1:5555/api"

// Get user data from localStorage (Sync - for initial render)
export function getUserStats(): UserStats {
  if (typeof window === "undefined") {
    return getDefaultUserStats()
  }
  const stored = localStorage.getItem("userStats")
  return stored ? JSON.parse(stored) : getDefaultUserStats()
}

// Fetch user data from API (Async)
export async function fetchUserStats(): Promise<UserStats> {
  const { user, isGuest } = getAuthState()

  if (isGuest || !user) {
    return getUserStats()
  }

  try {
    const response = await fetch(`${API_URL}/users/${user.id}`)
    if (response.ok) {
      const data = await response.json()
      const stats: UserStats = {
        level: data.level,
        xp: data.xp,
        totalFocusMinutes: data.total_focus_minutes,
        todayFocusMinutes: 0, // Backend doesn't track daily/weekly yet
        weekFocusMinutes: 0,
        tasksCompleted: 0, // Backend doesn't track this count yet
        currentStreak: data.current_streak,
        badges: [], // Need to fetch badges separately or include in user response
      }
      // Update local storage to keep sync
      if (typeof window !== "undefined") {
        localStorage.setItem("userStats", JSON.stringify(stats))
      }
      return stats
    }
  } catch (error) {
    console.error("Failed to fetch user stats", error)
  }
  return getUserStats()
}

export async function saveUserStats(stats: UserStats) {
  // Always save to local storage first for immediate UI update
  if (typeof window !== "undefined") {
    localStorage.setItem("userStats", JSON.stringify(stats))
  }

  const { user, isGuest } = getAuthState()
  if (isGuest || !user) return

  try {
    await fetch(`${API_URL}/users/${user.id}`, {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        xp: stats.xp,
        level: stats.level,
        current_streak: stats.currentStreak,
        total_focus_minutes: stats.totalFocusMinutes,
      }),
    })
  } catch (error) {
    console.error("Failed to save user stats", error)
  }
}

