export async function addXP(amount: number) {
  const stats = getUserStats()
  stats.xp += amount

  const xpNeededForLevel = stats.level * 100
  while (stats.xp >= xpNeededForLevel) {
    stats.xp -= xpNeededForLevel
    stats.level += 1
  }

  await saveUserStats(stats)
  return stats
}
