"use client"

import { useState, useEffect, useRef } from "react"
import JSConfetti from "js-confetti"
import { Button } from "@/components/ui/button"
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"
import { Input } from "@/components/ui/input"
import { Checkbox } from "@/components/ui/checkbox"
import { Progress } from "@/components/ui/progress"
import { GiftIcon, Trash2 } from "lucide-react"
import {
  getTasks,
  saveTasks,
  type Task,
  getQuests,
  saveQuests,
  addXP,
  getUserStats,
} from "@/lib/user-data"

/* ============================================================
   PRIORITY SYSTEM
   ============================================================ */
type Priority = "high" | "medium" | "low"

type TaskWithPriority = Task & {
  priority: Priority
}

const PRIORITY_META: Record<
  Priority,
  { label: string; icon: string; className: string }
> = {
  high: { label: "High Priority", icon: "🔴", className: "text-red-500" },
  medium: { label: "Medium Priority", icon: "⭐", className: "text-yellow-500" },
  low: { label: "Low Priority", icon: "🔔", className: "text-gray-400" },
}

export function TasksTab({ onStatsUpdate }: { onStatsUpdate: () => void }) {
  const [tasks, setTasks] = useState<TaskWithPriority[]>([])
  const [quests, setQuests] = useState(getQuests())
  const [newTaskTitle, setNewTaskTitle] = useState("")
  const [newPriority, setNewPriority] = useState<Priority>("medium")

  /* 🎊 JS-CONFETTI */
  const confettiRef = useRef<JSConfetti | null>(null)

  useEffect(() => {
    const stored = getTasks() as TaskWithPriority[]
    setTasks(
      stored.map((t) => ({
        ...t,
        priority: t.priority ?? "medium",
      }))
    )
    setQuests(getQuests())

    // init js-confetti once
    confettiRef.current = new JSConfetti()
  }, [])

  const fireConfetti = () => {
    confettiRef.current?.addConfetti({
      confettiColors: [
        "#22c55e", // green
        "#facc15", // gold
      ],
      confettiRadius: 5,
      confettiNumber: 150,
    })
  }

  const handleAddTask = () => {
    if (!newTaskTitle.trim()) return

    const newTask: TaskWithPriority = {
      id: Date.now().toString(),
      title: newTaskTitle,
      completed: false,
      createdAt: new Date(),
      priority: newPriority,
    }

    const updated = [...tasks, newTask]
    setTasks(updated)
    saveTasks(updated)
    setNewTaskTitle("")
    setNewPriority("medium")
  }

  const handleToggleTask = (taskId: string) => {
    const updated = tasks.map((t) =>
      t.id === taskId ? { ...t, completed: !t.completed } : t
    )

    const toggled = updated.find((t) => t.id === taskId)

    if (toggled?.completed) {
      // 🎊 REAL CONFETTI (VIDEO STYLE)
      fireConfetti()

      const stats = getUserStats()
      stats.tasksCompleted += 1

      const completedCount = updated.filter((t) => t.completed).length

      const updatedQuests = quests.map((q) => {
        if (q.id === "2" && !q.completed) {
          const progress = Math.min(completedCount, q.target)
          const completed = progress >= q.target
          if (completed && !q.completed) addXP(q.xpReward)
          return { ...q, progress, completed }
        }
        return q
      })

      saveQuests(updatedQuests)
      setQuests(updatedQuests)

      addXP(10)
      onStatsUpdate()
    }

    setTasks(updated)
    saveTasks(updated)
  }

  const handleDeleteTask = (taskId: string) => {
    const updated = tasks.filter((t) => t.id !== taskId)
    setTasks(updated)
    saveTasks(updated)
  }

  const dailyQuests = quests.filter((q) => q.type === "daily")
  const weeklyQuests = quests.filter((q) => q.type === "weekly")

  const parchmentStyle = {
    backgroundImage: "url('/images/paper.jpg')",
    backgroundSize: "cover",
    backgroundRepeat: "no-repeat",
    backgroundPosition: "center",
  }

  return (
    <div className="max-w-6xl mx-auto space-y-8 relative">
      <div className="grid gap-8 md:grid-cols-2">

        {/* 🎅 THE NICE LIST */}
        <Card
          className="relative bg-transparent text-[#3b2f2f] font-handwritten overflow-hidden"
          style={parchmentStyle}
        >
          <CardHeader>
            <CardTitle className="text-2xl">🎅 The Nice List</CardTitle>
            <CardDescription className="text-green-700 font-semibold">
              What will you finish today?
            </CardDescription>
          </CardHeader>

          <CardContent className="space-y-4">
            <div className="flex gap-2">
              <Input
                placeholder="Add a study task..."
                value={newTaskTitle}
                onChange={(e) => setNewTaskTitle(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && handleAddTask()}
                className="font-handwritten bg-white border-2"
              />

              <select
                value={newPriority}
                onChange={(e) => setNewPriority(e.target.value as Priority)}
                className="rounded-md border px-2 text-sm bg-white"
              >
                <option value="high">🔴 High</option>
                <option value="medium">⭐ Medium</option>
                <option value="low">🔔 Low</option>
              </select>

              <Button
                onClick={handleAddTask}
                size="icon"
                className="bg-red-500 hover:bg-red-600"
              >
                <GiftIcon className="h-5 w-5" />
              </Button>
            </div>

            {tasks.map((task) => {
              const meta = PRIORITY_META[task.priority]

              return (
                <div
                  key={task.id}
                  className="flex items-center gap-3 p-3 rounded-lg bg-white/80"
                >
                  <Checkbox
                    checked={task.completed}
                    onCheckedChange={() => handleToggleTask(task.id)}
                  />
                  <span className="flex-1 font-handwritten text-lg">
                    {task.title}
                  </span>
                  <span className={meta.className}>{meta.icon}</span>
                  <Button
                    variant="ghost"
                    size="icon"
                    onClick={() => handleDeleteTask(task.id)}
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </div>
              )
            })}
          </CardContent>
        </Card>

        {/* 🎁 QUESTS (UNCHANGED) */}
        <div className="space-y-4">
          {[{ title: "Daily Quests", data: dailyQuests }, { title: "Weekly Quests", data: weeklyQuests }].map(
            (section) => (
              <Card
                key={section.title}
                className="bg-transparent"
                style={parchmentStyle}
              >
                <CardHeader>
                  <CardTitle className="flex items-center gap-2 text-green-700">
                    <GiftIcon className="h-5 w-5" />
                    {section.title}
                  </CardTitle>
                </CardHeader>

                <CardContent className="space-y-4">
                  {section.data.map((quest) => (
                    <div
                      key={quest.id}
                      className="p-4 rounded-lg bg-white/80"
                    >
                      <h4 className="font-semibold text-green-700">
                        {quest.title}
                      </h4>
                      <p className="text-sm text-green-700/80">
                        {quest.description}
                      </p>
                      <Progress
                        value={(quest.progress / quest.target) * 100}
                        className="h-2 mt-2"
                      />
                    </div>
                  ))}
                </CardContent>
              </Card>
            )
          )}
        </div>
      </div>
    </div>
  )
}
